# ------------------------------------------------------------------ OA 08 · clase 2
L(OA8, 2,
  MAT,
  "Aprenderé a relacionar mi experiencia y mis conocimientos con un texto sin que sea obligatorio contar mi vida, y a mantener siempre la evidencia del texto como base.",
  ["Formulo preguntas interpretativas.", "Distingo experiencia propia y ajena."],
  ["Al interpretar, se puede relacionar el texto con la experiencia personal y con los conocimientos. Pero «experiencia» no significa contar la intimidad. Puede ser una experiencia ajena, como lo que sé por otras lecturas, noticias o conversaciones; puede ser un conocimiento de otras asignaturas, como saber que el agua es escasa en un desierto; o una situación imaginada. Nadie está obligado a hablar de su vida privada para interpretar un texto.",
   "La regla central es esta: lo que traigo de afuera ilumina, pero la evidencia del texto sostiene. Si digo «el relato muestra que reconocer un error puede proteger al grupo», lo apoyo en el pasaje donde Iván propone detenerse. Después puedo agregar un conocimiento: «en un lugar donde el agua es escasa, un error de cálculo pone en riesgo a todos». Si trajera solo mi opinión («a mí me parece») sin pasaje, no sería una interpretación.",
   "Para relacionar sin exponerse conviene usar frases generales: «a veces una persona siente vergüenza de un error y duda si contarlo». También se puede usar un caso hipotético: «imaginemos un equipo que descubre una falla antes de una presentación». Estas conexiones muestran cómo el texto dialoga con la vida sin entregar datos privados. Y si alguien decide compartir algo personal, se respeta y se vuelve al texto."],
  [("conocimiento previo", "lo que se sabe por estudio, lectura o información, aparte del texto"), ("experiencia ajena", "la que vive otra persona y se conoce por lectura o relato"), ("caso hipotético", "situación imaginada para comprender una idea"), ("intimidad", "lo privado de una persona")],
  [("Una conexión adecuada", "Conexión A: «A mi hermano le pasó eso el sábado y lloró». Conexión B: «A veces una persona siente vergüenza de un error y duda si contarlo». ¿Cuál es mejor para un texto de clase?",
    ["A expone la vida privada de otra persona.", "B es general y no identifica a nadie.", "B es la adecuada."],
    "La B"),
   ("Evidencia y conocimiento", P1 + " Conocimiento: «En un desierto el agua es un recurso escaso». ¿Cómo ayuda al texto?",
    ["El texto dice que el agua no alcanzará.", "El conocimiento explica por qué es grave.", "Ilumina la gravedad del error de Iván."],
    "Explica por qué el error de Iván es grave")],
  [("Contar detalles personales para «probar» una interpretación.", "Se cree que lo personal es evidencia.", "Usa el texto como evidencia y lo personal solo si quieres y en términos generales."),
   ("Reemplazar el texto por la opinión personal.", "Se confunde interpretar con opinar.", "Cita el pasaje y luego agrega la conexión.")],
  ([E("¿Es obligatorio contar tu vida privada para interpretar un texto?", "No", "Se puede usar conocimientos y casos generales."),
    E("Lo que sé por otras asignaturas, ¿es un conocimiento previo o una experiencia íntima?", "Un conocimiento previo", "Es información que se aprendió."),
    E("¿Qué debe sostener la interpretación: la evidencia del texto o la opinión sola?", "La evidencia del texto", "Lo de afuera solo ilumina.")],
   [E("Frase A: «Mi mamá siempre se enoja cuando me equivoco». Frase B: «Muchas personas temen reconocer un error por vergüenza». ¿Cuál protege mejor la intimidad?", "La B", "No nombra ni identifica a nadie."),
    E("Un compañero dice: «El relato me parece bueno porque sí». ¿Qué le falta para interpretar? A) un pasaje que respalde su idea B) otra opinión personal C) un recuerdo personal", "A) un pasaje que respalde su idea", "Una interpretación se apoya en el texto."),
    E("Caso hipotético: «Imaginemos un equipo que descubre una falla antes de una presentación». ¿Se relaciona con el dilema de Iván?", "Sí", "También hay que decidir si decir un error a tiempo.")],
   [E(P2 + " Conocimiento: «En un viaje largo, perder tiempo puede tener costos». ¿Qué ayuda a entender de Dalia? A) por qué le preocupa perder un día B) quién es su hermano C) de qué material es la lámpara", "A) por qué le preocupa perder un día", "Explica el costo que ella teme."),
    E("Escribe qué parte es evidencia del texto: «Iván propone detenerse» o «a mí me da miedo equivocarme».", "«Iván propone detenerse»", "Está en el relato; lo otro es una experiencia personal."),
    E("Una conexión que cuenta un detalle privado de otra persona, ¿es adecuada para compartir en clase?", "No", "Se debe cuidar la intimidad de otros.")],
   [E("Un lector afirma: «Si no cuento mi vida, mi interpretación no vale». ¿Qué responde la clase? A) vale si se apoya en el texto y en conocimientos B) tiene razón C) debe contarla igual", "A) vale si se apoya en el texto y en conocimientos", "La autobiografía no es obligatoria."),
    E("Dos interpretaciones: la de Ana cita P3 y la de Luis solo dice «yo habría hecho lo mismo». ¿Cuál tiene evidencia?", "La de Ana", "Cita un pasaje del relato.")],
   [E("Ordena una interpretación: (a) conexión con un conocimiento, (b) tesis, (c) cita del texto. Escribe el orden más claro.", "b, c, a", "Primero la tesis, luego la evidencia y después la conexión que ilumina."),
    E("Si alguien decide compartir un recuerdo personal, ¿qué hace el grupo? A) lo respeta y vuelve al texto con una pregunta B) pide más detalles C) lo comenta fuera", "A) lo respeta y vuelve al texto con una pregunta", "Se protege la intimidad y se reconduce.")]),
  [E("Tu curso debe escribir sobre el dilema de Iván y no quieres contar nada personal. ¿Qué opción es válida? A) usar un caso hipotético sobre un equipo escolar B) contar un secreto de un compañero C) no escribir nada", "A) usar un caso hipotético sobre un equipo escolar", "Es una conexión general que no expone a nadie.")],
  [E("¿Qué es un caso hipotético?", "Una situación imaginada para comprender una idea", "No requiere datos privados."),
   E("¿La evidencia del texto puede ser reemplazada por la opinión?", "No", "La opinión sola no sostiene."),
   E("¿Se pueden usar conocimientos de otras asignaturas?", "Sí", "Ayudan a iluminar el texto.")],
  ("Escribe una interpretación de 5 líneas sobre P3 («" + P3 + "») con: una tesis, una cita, un conocimiento o caso hipotético (sin datos privados) y una frase que indique qué parte es evidencia y cuál es conexión.",
   "Tesis: Iván prefiere cuidar a todos antes que ganar tiempo. Cita: «Prefiero que nos detengamos y repartamos lo que queda». Conexión: en un desierto el agua escasa vuelve grave un error de cálculo. La cita es la evidencia; el conocimiento sobre el desierto es la conexión.",
   ["incluye tesis y cita", "usa conexión general", "distingue evidencia y conexión"], ["párrafo de cinco líneas"], ["datos privados", "opinión sin cita"], "Marca en distintos colores la evidencia y la conexión."),
  "Piensa en un caso hipotético parecido al de Iván y explícalo a alguien sin nombrar a nadie.",
  "Escribe dos conexiones generales distintas para el mismo pasaje.")

